import {INQUIRY_STATUSES,nights,interval,quote} from './model.js';
export function filterInquiries(rows,{search='',status='',apartment='',arrivalFrom='',arrivalTo=''}={},apartments=[]){
 const term=search.trim().toLocaleLowerCase('hr');
 return rows.filter(i=>(!status||i.status===status)&&(!apartment||i.apartment===apartment)&&(!arrivalFrom||i.arrival>=arrivalFrom)&&(!arrivalTo||i.arrival<=arrivalTo)&&(!term||[i.name,i.email,i.phone,i.id,i.arrival,i.departure,i.internalNote,apartments.find(a=>a.slug===i.apartment)?.name].join(' ').toLocaleLowerCase('hr').includes(term)));
}
export function inquiryReply(i,site){
 const a=site.apartments.find(a=>a.slug===i.apartment),q=a?quote(a,i.arrival,i.departure):null;
 const l=['hr','en','de','cs'].includes(i.language)?i.language:'hr';
 const w={hr:['Pozdrav','Hvala na upitu za boravak.','Apartman','Po dogovoru','Dolazak','Odlazak','Odrasli','Djeca','Cijena smještaja prema cjeniku','Dostupnost, konačnu ponudu i eventualne dodatne troškove potvrđujemo zasebno.','Javit ćemo vam se s potvrdom dostupnosti i ponudom.','Ova poruka nije potvrda rezervacije.','Srdačan pozdrav'],en:['Hello','Thank you for your stay enquiry.','Apartment','To be arranged','Check-in','Check-out','Adults','Children','Accommodation price from the price list','Availability, the final offer and any additional charges will be confirmed separately.','We will get back to you with availability and an offer.','This message is not a booking confirmation.','Kind regards'],cs:['Dobrý den','Děkujeme za poptávku pobytu.','Apartmán','Dle domluvy','Příjezd','Odjezd','Dospělí','Děti','Cena ubytování podle ceníku','Dostupnost, konečnou nabídku a případné příplatky potvrdíme samostatně.','Ozveme se vám s dostupností a nabídkou.','Tato zpráva není potvrzením rezervace.','S pozdravem'],de:['Hallo','Vielen Dank für Ihre Aufenthaltsanfrage.','Apartment','Nach Vereinbarung','Anreise','Abreise','Erwachsene','Kinder','Unterkunftspreis laut Preisliste','Verfügbarkeit, das endgültige Angebot und mögliche Zusatzkosten bestätigen wir gesondert.','Wir melden uns mit Verfügbarkeit und einem Angebot.','Diese Nachricht ist keine Buchungsbestätigung.','Freundliche Grüße']}[l];
 const total=q?.meetsMinimum?new Intl.NumberFormat({hr:'hr-HR',en:'en-GB',de:'de-DE',cs:'cs-CZ'}[l],{style:'currency',currency:'EUR'}).format(q.total):null;
 return [`${w[0]} ${i.name},`,'',w[1],`${w[2]}: ${a?.name||w[3]}`,`${w[4]}: ${i.arrival}`,`${w[5]}: ${i.departure}`,`${w[6]}: ${i.adults}`,`${w[7]}: ${i.children||0}`,'',...(total?[`${w[8]}: ${total}`,w[9]]:[w[10]]),'',w[11],'',`${w[12]},`,site.name].join('\n');
}
export function demoInquiries(apartments){return [
 {id:'00000000-0000-4000-8000-000000000001',name:'Ogledna gošća Ana',email:'ana@example.test',apartment:'maslina',arrival:'2027-07-01',departure:'2027-07-08',adults:2,children:1,message:'OGLEDNI UPIT: zanima nas boravak s djetetom. Ima li apartman terasu?',language:'hr',status:'new',internalNote:'',workflowRevision:0,createdAt:'2026-10-20T09:00:00Z'},
 {id:'00000000-0000-4000-8000-000000000002',name:'Demo guest Alex',email:'alex@example.test',apartment:'lavanda',arrival:'2027-08-10',departure:'2027-08-17',adults:4,children:0,message:'DEMO ENQUIRY: we would like information about parking.',language:'en',status:'offered',internalNote:'Ogledna bilješka: poslati detalje parkiranja nakon potvrde domaćina.',workflowRevision:0,createdAt:'2026-10-19T09:00:00Z'},
 {id:'00000000-0000-4000-8000-000000000003',name:'Beispielgast Mia',email:'mia@example.test',apartment:'more',arrival:'2027-06-12',departure:'2027-06-16',adults:2,children:0,message:'BEISPIELANFRAGE: wir möchten im Juni anreisen.',language:'de',status:'replied',internalNote:'',workflowRevision:0,createdAt:'2026-10-18T09:00:00Z'}
 ].map((row,i)=>({...row,apartment:apartments?.[i]?.slug||row.apartment}));}
export function createInquiryInbox({site,esc,getRows,isDemo,save,refresh,retry}){
 let filters={search:'',status:'',apartment:'',arrivalFrom:'',arrivalTo:''};
 const edits=new Map();
 const apartmentName=i=>site.apartments.find(a=>a.slug===i.apartment)?.name||i.apartment||'Svejedno';
 function rowMarkup(i){const edit=edits.get(i.id)||{},status=edit.status??i.status,note=edit.internalNote??i.internalNote??'',reply=edit.reply??inquiryReply(i,site);return `<details class="inquiry-admin" data-inbox-row="${esc(i.id)}"><summary><span><strong>${esc(i.name)}</strong><span class="inbox-summary">${esc(apartmentName(i))} · ${esc(i.arrival)} → ${esc(i.departure)}</span></span><span class="status-pill ${i.status==='new'?'ready':''}">${esc(INQUIRY_STATUSES[i.status]||'Nepoznat status')}</span></summary><div class="inbox-detail"><dl class="inbox-facts"><div><dt>Kontakt</dt><dd><a href="mailto:${esc(i.email)}">${esc(i.email)}</a>${i.phone?`<br>${esc(i.phone)}`:''}</dd></div><div><dt>Gosti / noćenja</dt><dd>${esc(i.adults)} odraslih · ${esc(i.children||0)} djece · ${interval(i.arrival,i.departure)?nights(i.arrival,i.departure):'—'} noći</dd></div><div><dt>Zaprimljeno</dt><dd>${esc(i.createdAt?.slice(0,16).replace('T',' ')||'—')} UTC</dd></div></dl><h3>Poruka gosta</h3><p class="preserve-lines">${esc(i.message||'Bez dodatne poruke.')}</p><form data-inbox-save="${esc(i.id)}" data-workflow-revision="${edit.workflowRevision??i.workflowRevision??0}" class="inbox-workflow"><label class="field">Status upita<select name="status">${Object.entries(INQUIRY_STATUSES).map(([key,label])=>`<option value="${key}" ${status===key?'selected':''}>${label}</option>`).join('')}</select></label><label class="field">Privatna bilješka<textarea name="internalNote" maxlength="5000" rows="3" placeholder="Dogovori, pitanja i podsjetnici za administratore…">${esc(note)}</textarea></label><p class="section-note">Bilješka je vidljiva samo administratorima. Status „Potvrđeno” ne dodaje zauzeće u kalendar; potvrđeni termin unesite u „Zauzeti termini”.</p><button class="btn" type="submit">Spremi status i bilješku ↗</button><p class="inbox-row-status" data-save-status role="status"></p></form><details class="inbox-reply"><summary>Pripremi odgovor gostu</summary><label class="field">Predložak na jeziku gosta<textarea data-inbox-reply="${esc(i.id)}" rows="10" maxlength="10000">${esc(reply)}</textarea></label><div class="inbox-actions"><button type="button" class="btn outline" data-copy-reply="${esc(i.id)}">Kopiraj odgovor</button><a class="btn outline" data-email-reply="${esc(i.id)}" href="mailto:${esc(i.email)}?subject=${encodeURIComponent('Adria Maja — '+i.arrival)}&body=${encodeURIComponent(reply)}">Otvori e-poštu ↗</a></div><p class="section-note">Predložak uredite prije slanja. Slanje potvrđujete u svojoj aplikaciji za e-poštu. Otvaranje predloška ne mijenja status upita.</p><p data-copy-status role="status"></p></details><p class="section-note">Dostava izvornog upita domaćinu: ${i.delivery?.host?.status==='sent'?'predano servisu':'nije potvrđeno'} · Potvrda primitka gostu: ${i.delivery?.guest?.status==='sent'?'predano servisu':'nije potvrđeno'}</p>${!isDemo()&&(i.delivery?.host?.status!=='sent'||i.delivery?.guest?.status!=='sent')?`<button class="btn outline" data-inbox-retry="${esc(i.id)}">Ponovi dostavu izvornog upita</button>`:''}</div></details>`}
 function listMarkup(){const all=getRows(),rows=filterInquiries(all,filters,site.apartments);return `<p class="section-note" role="status">Prikazano ${rows.length} od ${all.length} učitanih upita.</p>${rows.length?rows.map(rowMarkup).join(''):`<div class="empty-state">${all.length?'Nema upita koji odgovaraju odabranim filtrima.':'Još nema zaprimljenih upita.'}</div>`}`}
 function markup(){const rows=getRows();return `<div class="admin-card"><div class="admin-toolbar"><h2>Upiti gostiju.</h2>${isDemo()?'<button class="btn outline" id="load-inbox-demo">Učitaj ogledne upite</button>':'<button class="btn outline" id="refresh-inquiries">Osvježi ↻</button>'}</div><p class="section-note">${isDemo()?'Ogledni primjeri nisu stvarni gosti. Promjene upita vrijede do zatvaranja oglednog pregleda i ne objavljuju se.':'Prikazuje se najnovijih 100 upita iz obrasca. WhatsApp poruke ostaju u WhatsAppu i ne dodaju se automatski u ovaj popis.'}</p><div class="inbox-counts">${[['new','Novi'],['offered','Ponuda poslana'],['confirmed','Potvrđeni']].map(([key,label])=>`<div><strong>${rows.filter(i=>i.status===key).length}</strong><span>${label}</span></div>`).join('')}</div><form id="inbox-filters" class="inbox-filters" role="search"><label class="field">Pretraži upite<input type="search" name="search" maxlength="200" placeholder="Ime, e-mail, termin, bilješka…" value="${esc(filters.search)}"></label><label class="field">Status<select name="status"><option value="">Svi statusi</option>${Object.entries(INQUIRY_STATUSES).map(([key,label])=>`<option value="${key}" ${filters.status===key?'selected':''}>${label}</option>`).join('')}</select></label><label class="field">Apartman<select name="apartment"><option value="">Svi apartmani</option>${site.apartments.map(a=>`<option value="${esc(a.slug)}" ${filters.apartment===a.slug?'selected':''}>${esc(a.name)}</option>`).join('')}</select></label><label class="field">Dolazak od<input name="arrivalFrom" type="date" value="${esc(filters.arrivalFrom)}"></label><label class="field">Dolazak do<input name="arrivalTo" type="date" value="${esc(filters.arrivalTo)}"></label><button class="btn outline" type="reset">Očisti filtre</button></form><div id="inbox-list">${listMarkup()}</div></div>`}
 function bindRows(){document.querySelectorAll('[data-inbox-row]').forEach(row=>{const id=row.dataset.inboxRow,i=getRows().find(i=>i.id===id),f=row.querySelector('[data-inbox-save]'),reply=row.querySelector('[data-inbox-reply]');const capture=()=>edits.set(id,{status:f.elements.status.value,internalNote:f.elements.internalNote.value,reply:reply.value,workflowRevision:Number(f.dataset.workflowRevision)});f.addEventListener('input',capture);reply.oninput=()=>{capture();row.querySelector('[data-email-reply]').href=`mailto:${i.email}?subject=${encodeURIComponent('Adria Maja — '+i.arrival)}&body=${encodeURIComponent(reply.value)}`};f.onsubmit=async e=>{e.preventDefault();capture();const button=f.querySelector('button'),status=row.querySelector('[data-save-status]');button.disabled=true;status.textContent='Spremanje…';try{await save({...i,status:f.elements.status.value,internalNote:f.elements.internalNote.value,workflowRevision:Number(f.dataset.workflowRevision)});f.dataset.workflowRevision=i.workflowRevision;status.textContent=isDemo()?'Ogledna promjena spremljena za ovaj pregled.':'Status i bilješka su spremljeni.';row.querySelector('summary>.status-pill').textContent=INQUIRY_STATUSES[i.status];row.querySelector('summary>.status-pill').classList.toggle('ready',i.status==='new');edits.set(id,{reply:reply.value});if(!filterInquiries([i],filters,site.apartments).length){document.querySelector('#admin-notice').textContent=status.textContent;document.querySelector('#inbox-list').innerHTML=listMarkup();bindRows()}document.querySelectorAll('.inbox-counts strong').forEach((el,n)=>el.textContent=getRows().filter(r=>r.status===['new','offered','confirmed'][n]).length)}catch(error){status.textContent=error.message}finally{button.disabled=false}};row.querySelector('[data-copy-reply]').onclick=async()=>{const status=row.querySelector('[data-copy-status]');try{await navigator.clipboard.writeText(reply.value);status.textContent='Odgovor je kopiran.'}catch{status.textContent='Kopiranje nije dostupno. Označite tekst i kopirajte ga ručno.'}};const repeat=row.querySelector('[data-inbox-retry]');if(repeat)repeat.onclick=async()=>{repeat.disabled=true;try{await retry(id);repeat.textContent='Dostava obrađena — osvježite popis za status.'}catch(error){row.querySelector('[data-save-status]').textContent=error.message;repeat.disabled=false}}})}
 function bind(){const f=document.querySelector('#inbox-filters');if(!f)return;const apply=()=>{filters=Object.fromEntries(new FormData(f));document.querySelector('#inbox-list').innerHTML=listMarkup();bindRows()};f.onsubmit=e=>e.preventDefault();f.oninput=apply;f.onchange=apply;f.onreset=()=>requestAnimationFrame(apply);bindRows();const refreshButton=document.querySelector('#refresh-inquiries');if(refreshButton)refreshButton.onclick=async()=>{refreshButton.disabled=true;try{await refresh();document.querySelector('#inbox-list').innerHTML=listMarkup();bindRows();document.querySelectorAll('.inbox-counts strong').forEach((el,n)=>el.textContent=getRows().filter(r=>r.status===['new','offered','confirmed'][n]).length)}catch(error){document.querySelector('#admin-notice').textContent=error.message}finally{refreshButton.disabled=false}}}
 function reset(){filters={search:'',status:'',apartment:'',arrivalFrom:'',arrivalTo:''};edits.clear()}
 return {markup,bind,reset};
}
